[CmdletBinding(SupportsShouldProcess=$true)]
param(
 [ValidateSet('Check','Capture','Apply','Verify','VerifyReboot','Rollback')][string]$Action='Check',
 [string]$StatePath="$PSScriptRoot\state.json",
 [string]$LogPath="$PSScriptRoot\events.jsonl"
)
Set-StrictMode -Version 2.0
$ErrorActionPreference='Stop'
function Log($event,$data){$row=[ordered]@{utc=(Get-Date).ToUniversalTime().ToString('o');experiment='EXP-131';action=$Action;event=$event;computer=$env:COMPUTERNAME;userSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;data=$data};($row|ConvertTo-Json -Compress -Depth 10)|Add-Content $LogPath}
function Elevation {$p=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent());if(-not $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Elevation required'}}
function ExePath($p){if($p -match '^\s*"([^"]+\.exe)"'){return $matches[1]};if($p -match '^\s*([^\s]+\.exe)'){return $matches[1]};throw 'Executable path parse failed'}
function Mdm {$r='HKLM:\SOFTWARE\Microsoft\Enrollments';if(Test-Path $r){foreach($k in Get-ChildItem $r -ErrorAction SilentlyContinue){$p=Get-ItemProperty $k.PSPath -ErrorAction SilentlyContinue;if($p.ProviderID -or $p.DiscoveryServiceFullURL){return $true}}};$false}
function Candidate {Elevation;$os=Get-CimInstance Win32_OperatingSystem;$cs=Get-CimInstance Win32_ComputerSystem;if($os.Caption -notmatch 'Windows 11' -or $cs.Manufacturer -notmatch 'HP|Hewlett-Packard'){throw 'Unsupported platform'};if($cs.PartOfDomain -or (Mdm)){throw 'Enterprise management state refused'};$all=@(Get-CimInstance Win32_Service|Where-Object {$_.DisplayName -match '(?i)HP.*Comm.*Recover' -or $_.PathName -match '(?i)HPCommRecovery\.exe'});if($all.Count -ne 1){throw 'HP Comm Recovery service absent or ambiguous'};$s=$all[0];$exe=ExePath $s.PathName;if((Split-Path $exe -Leaf) -notmatch '(?i)^HPCommRecovery\.exe$'){throw 'Executable identity refused'};if(-not(Test-Path $exe)){throw 'Executable missing'};$sig=Get-AuthenticodeSignature $exe;if($sig.Status -ne 'Valid' -or $sig.SignerCertificate.Subject -notmatch '(?i)HP Inc|Hewlett-Packard'){throw 'HP publisher signature refused'};$g=Get-Service $s.Name;$deps=@($g.ServicesDependedOn|% Name);$dependents=@($g.DependentServices|% Name);foreach($n in @($deps+$dependents)){if($n -match '(?i)WinDefend|mpssvc|bfe|wuauserv|cryptsvc|Tailscale|TermService|RasMan|NlaSvc|Dhcp|Dnscache'){throw "Protected dependency refused: $n"}};$key="HKLM:\SYSTEM\CurrentControlSet\Services\$($s.Name)";$d=(Get-ItemProperty $key -Name DelayedAutoStart -ErrorAction SilentlyContinue).DelayedAutoStart;if($null -eq $d){$d=0};[pscustomobject]@{Service=$s;Exe=$exe;Hash=(Get-FileHash $exe -Algorithm SHA256).Hash;Signature=$sig.SignerCertificate.Subject;Dependencies=$deps;Dependents=$dependents;Delayed=[int]$d;Key=$key;Build=$os.BuildNumber}}
function Save($c){$s=$c.Service;$v=[ordered]@{schema=1;computer=$env:COMPUTERNAME;name=$s.Name;display=$s.DisplayName;path=$s.PathName;exe=$c.Exe;hash=$c.Hash;signature=$c.Signature;startMode=$s.StartMode;delayed=$c.Delayed;state=$s.State;dependencies=$c.Dependencies;dependents=$c.Dependents;build=$c.Build};$v|ConvertTo-Json -Depth 8|Set-Content $StatePath;Log 'captured' @{name=$s.Name;startMode=$s.StartMode;delayed=$c.Delayed};$v}
function ReadState {if(-not(Test-Path $StatePath)){throw 'State missing'};$s=Get-Content $StatePath -Raw|ConvertFrom-Json;if($s.computer -ne $env:COMPUTERNAME){throw 'State machine mismatch'};$s}
function Drift($s,$c){if($s.name -ne $c.Service.Name -or $s.path -ne $c.Service.PathName -or $s.exe -ne $c.Exe -or $s.hash -ne $c.Hash -or $s.signature -ne $c.Signature){throw 'Identity drift refused'};if(Compare-Object @($s.dependencies) @($c.Dependencies)){throw 'Dependency drift refused'};if(Compare-Object @($s.dependents) @($c.Dependents)){throw 'Dependent drift refused'}}
function SetMode($mode,$delayed){Set-Service $script:c.Service.Name -StartupType $mode;Set-ItemProperty $script:c.Key DelayedAutoStart -Type DWord -Value $delayed}
$script:c=Candidate;$svc=$c.Service
switch($Action){
 'Check' {Log 'supported' @{name=$svc.Name;startMode=$svc.StartMode;delayed=$c.Delayed;hash=$c.Hash};$c}
 'Capture' {Save $c|Out-Null}
 'Apply' {if($svc.StartMode -ne 'Auto'){throw 'Automatic baseline required'};if(-not(Test-Path $StatePath)){Save $c|Out-Null};if($c.Delayed -eq 1){Log 'already-applied' @{name=$svc.Name};break};if($PSCmdlet.ShouldProcess($svc.Name,'Set Automatic Delayed Start')){SetMode Automatic 1};if($WhatIfPreference){Log 'dry-run' @{proposed='AutomaticDelayedStart'};break};$n=Candidate;if($n.Service.StartMode -ne 'Auto' -or $n.Delayed -ne 1){throw 'Apply verification failed'};Log 'applied' @{delayed=1}}
 'Verify' {$n=Candidate;if($n.Service.StartMode -ne 'Auto' -or $n.Delayed -ne 1){throw 'Verification failed'};Log 'verified' @{delayed=1}}
 'VerifyReboot' {$s=ReadState;$n=Candidate;Drift $s $n;if($n.Service.StartMode -ne 'Auto' -or $n.Delayed -ne 1){throw 'Reboot persistence failed'};Log 'reboot-verified' @{state=$n.Service.State}}
 'Rollback' {$s=ReadState;Drift $s $c;if($WhatIfPreference){$null=$PSCmdlet.ShouldProcess($svc.Name,"Restore $($s.startMode), delayed=$($s.delayed)");Log 'rollback-dry-run' @{startMode=$s.startMode;delayed=$s.delayed};break};if($PSCmdlet.ShouldProcess($svc.Name,'Restore exact captured startup state')){$m=if($s.startMode -eq 'Auto'){'Automatic'}elseif($s.startMode -eq 'Manual'){'Manual'}else{throw 'Unsupported captured mode'};SetMode $m ([int]$s.delayed);$st=(Get-Service $svc.Name).Status;if($s.state -eq 'Running' -and $st -ne 'Running'){Start-Service $svc.Name}elseif($s.state -eq 'Stopped' -and $st -eq 'Running'){Stop-Service $svc.Name -Force}};$n=Candidate;if($n.Service.StartMode -ne $s.startMode -or $n.Delayed -ne [int]$s.delayed){throw 'Rollback verification failed'};Log 'rolled-back' @{startMode=$n.Service.StartMode;delayed=$n.Delayed}}
}
